, "spa", "bakery", "pharmacy", "gym"]}, "tiers": {"fast": "muse-spark-1.3", "workhorse": "muse-spark-1.3", "decision": "muse-wonder-1.0"}, "vocabulary": ["founder", "co-founder", "proprietor", "director", "manager", "handling", "strain", "volume", "manual", "replies", "customers", "growth", "direct", "operation", "evidence", "quoted", "staff", "employees", "people", "team", "revenue", "sales", "online", "retail", "wholesale", "branch", "branches", "headcount", "total", "managing", "hiring", "funding", "expansion", "new", "post", "job", "change", "review", "activity", "push", "opening", "launch", "promotion", "selling", "save", "time", "need", "orders", "messages", "late", "lost", "busy", "daily", "grow", "reach", "respond", "follow", "leads", "page", "shop", "shops", "owner", "owners", "small", "local", "help", "service", "services", "content", "chatbot", "chatbots", "automation", "inquiry", "inquiries", "demand", "interest", "surge", "request", "requests", "offer", "offers", "recent", "property", "renovation", "reliable", "simplify", "sourcing", "menu", "chef", "staying", "partner", "partners", "signal", "signals", "seeking"], "profile_keys": ["sources", "lead_unit", "hard_filters", "decision_maker_titles", "research_fields", "size_fit", "outreach_angles", "exclusions"]};
// SF0 draft validator — pure, deterministic. Returns {violations:[{id,detail}], cost_usd}
const FUNC = new Set(['in','at','of','the','and','for','a','an','with','near','best','top','shops','stores','services','service','yangon','myanmar','thailand','page','pages','facebook','tiktok','messenger','order','orders','reviews','review','owner','run','small','business','businesses','sme','local','your','you','their','they','them','our','we','it','its','this','that','these','those','on','by','from','per','via','focus']);
function canon(s){ return String(s||'').normalize('NFC').toLowerCase(); }
function tokens(s){ return canon(s).split(/[^a-z0-9\u1000-\u109f]+/).filter(t=>t.length>0); }
function buildAllowlist(inputs, reg){
  const allow = new Set(FUNC);
  const add = (v)=>{ if(typeof v==='string') tokens(v).forEach(t=>allow.add(t)); };
  // notes is deliberately NOT an allowlist source (Wonder delta Condition 1, 2026-11-19):
  // free-text notes must never mint allowlist tokens. Structured fields only.
  ['business_name','what_they_sell','customer_in_users_words','decision_maker','ideal_size','price_range'].forEach(k=>add(inputs[k]));
  (inputs.locations||[]).forEach(add); (inputs.exclusions||[]).forEach(add);
  Object.keys(reg.gazetteer.locations).forEach(l=>{ allow.add(canon(l)); (reg.gazetteer.locations[l]||[]).forEach(a=>allow.add(canon(a))); });
  reg.gazetteer.categories.forEach(c=>tokens(c).forEach(t=>allow.add(t)));
  reg.research_fields.forEach(f=>tokens(f.replace(/_/g,' ')).forEach(t=>allow.add(t)));
  reg.size_bands.forEach(b=>tokens(b.replace(/_/g,' ')).forEach(t=>allow.add(t)));
  (reg.vocabulary||[]).forEach(w=>tokens(w).forEach(t=>allow.add(t)));
  Object.keys(reg.sources).forEach(s=>tokens(s.replace(/_/g,' ')).forEach(t=>allow.add(t)));
  return allow;
}
function numbersIn(s){ return (String(s||'').match(/\d+(?:\.\d+)?/g)||[]); }
function validateDraft(draft, inputs, reg){
  const arr = (v, where) => { if (Array.isArray(v)) return v; if (v == null) return []; bad0('SCHEMA_TYPE', where + ' must be an array'); return []; };
  function bad0(id, detail){ V0.push({id, detail}); }
  const V0 = [];
  const V=[]; const bad=(id,detail)=>V.push({id,detail});
  const allow = buildAllowlist(inputs, reg);
  const inputNumbers = new Set();
  ['ideal_size','price_range'].forEach(k=>numbersIn(inputs[k]).forEach(n=>inputNumbers.add(n)));
  (inputs.locations||[]).forEach(l=>numbersIn(l).forEach(n=>inputNumbers.add(n)));
  const checkTokens=(text, where)=>{
    tokens(text).forEach(t=>{ if(!allow.has(t)) bad('TOKEN_NOT_ALLOWLISTED', where+': "'+t+'"'); });
    numbersIn(text).forEach(n=>{ if(!inputNumbers.has(n) && !reg.size_bands.join(' ').includes(n)) bad('NUMBER_NOT_ALLOWLISTED', where+': '+n); });
  };
  // 1 schema
  const topKeys = Object.keys(draft||{});
  ['business_context','profile','rubric'].forEach(k=>{ if(!topKeys.includes(k)) bad('SCHEMA_MISSING_KEY', k); });
  topKeys.forEach(k=>{ if(!['business_context','profile','rubric'].includes(k)) bad('SCHEMA_EXTRA_KEY', k); });
  if(V.length){ V0.forEach(x=>V.push(x)); return {violations:V, cost_usd:0}; }
  const prof = draft.profile||{};
  const profKeys = reg.profile_keys;
  Object.keys(prof).forEach(k=>{ if(!profKeys.includes(k)) bad('SCHEMA_EXTRA_KEY','profile.'+k); });
  // injection screen on downstream-prompt fields
  const injFields = JSON.stringify([prof.outreach_angles||[], draft.business_context&&draft.business_context.notes||'']);
  if(/https?:\/\//i.test(injFields)) bad('INJECTION_URL','url in downstream field');
  if(/ignore (your|the) (brief|instructions|rules)|disregard|override/i.test(injFields)) bad('INJECTION_OVERRIDE','override phrase in downstream field');
  // 2 sources + queries
  let cost = 0; const seenQ = new Set();
  const locTokens = new Set(); (inputs.locations||[]).forEach(l=>tokens(l).forEach(t=>locTokens.add(t)));
  const catTokens = new Set(); reg.gazetteer.categories.forEach(c=>tokens(c).forEach(t=>catTokens.add(t)));
  for(const src of arr(prof.sources,'profile.sources')){
    Object.keys(src).forEach(k=>{ if(!['source','queries','locations','platforms','enabled'].includes(k)) bad('SCHEMA_EXTRA_KEY', 'source.'+k); });
    if(!src.source) bad('SCHEMA_MISSING_KEY', 'source.source');
    if(src.source==='tavily_social' && typeof src.enabled !== 'boolean') bad('SCHEMA_MISSING_KEY', 'source.enabled (tavily_social needs an explicit boolean)');
    const spec = reg.sources[src.source];
    if(!spec){ bad('SOURCE_UNKNOWN', String(src.source)); continue; }
    const qs = arr(src.queries,'queries');
    if(qs.length > spec.max_queries) bad('QUERY_CAP', src.source+': '+qs.length+' > '+spec.max_queries);
    cost += src.source==='apify_maps' ? qs.length * spec.unit_price_usd * spec.max_results_per_query : qs.length * spec.unit_price_usd;
    for(const q of qs){
      if(!q || !String(q).trim()){ bad('QUERY_EMPTY', src.source); continue; }
      const key = canon(q).replace(/\s+/g,' ');
      if(seenQ.has(key)) bad('QUERY_DUP', q); seenQ.add(key);
      const qt = tokens(q);
      const hasLoc = qt.some(t=>locTokens.has(t)); const hasCat = qt.some(t=>catTokens.has(t));
      if(src.source==='apify_maps' && !(hasLoc && hasCat)) bad('QUERY_GRAMMAR_MAPS', q);
      if(src.source==='tavily_research' && !hasLoc) bad('QUERY_NO_LOCATION', q);
      if(src.source==='tavily_social' && !(src.locations||[]).some(l=>locTokens.has(canon(l)))) bad('QUERY_NO_LOCATION', src.source+' source locations');
      checkTokens(q, 'query');
      for(const ex of (inputs.exclusions||[])){
        const exT = tokens(ex); if(exT.length && exT.every(t=>qt.includes(t))) bad('EXCLUSION_CONTRADICTED', q+' vs exclusion "'+ex+'"');
      }
    }
    if(src.source==='tavily_social'){ (src.platforms||[]).forEach(p=>{ if(!spec.platforms.includes(p)) bad('SOURCE_UNKNOWN','platform '+p); }); }
  }
  // 3 preservation
  const profLocText = canon(JSON.stringify(prof.sources||[])) + ' ' + canon(JSON.stringify((draft.business_context||{}).locations||[]));
  (inputs.locations||[]).forEach(l=>{ if(!tokens(l).every(t=>profLocText.includes(t))) bad('PRESERVE_LOCATION', l); });
  const profExcl = (prof.exclusions||[]).map(canon);
  (inputs.exclusions||[]).forEach(e=>{ if(!profExcl.some(x=>x.includes(canon(e)) || canon(e).includes(x))) bad('PRESERVE_EXCLUSION', e); });
