  Object.keys(reg.gazetteer.locations).forEach(l=>{ allow.add(canon(l)); (reg.gazetteer.locations[l]||[]).forEach(a=>allow.add(canon(a))); });
  reg.gazetteer.categories.forEach(c=>tokens(c).forEach(t=>allow.add(t)));
  reg.research_fields.forEach(f=>tokens(f.replace(/_/g,' ')).forEach(t=>allow.add(t)));
  reg.size_bands.forEach(b=>tokens(b.replace(/_/g,' ')).forEach(t=>allow.add(t)));
  (reg.vocabulary||[]).forEach(w=>tokens(w).forEach(t=>allow.add(t)));
  Object.keys(reg.sources).forEach(s=>tokens(s.replace(/_/g,' ')).forEach(t=>allow.add(t)));
