}
function numbersIn(s){ return (String(s||'').match(/\d+(?:\.\d+)?/g)||[]); }
function validateDraft(draft, inputs, reg){
  const arr = (v, where) => { if (Array.isArray(v)) return v; if (v == null) return []; bad0('SCHEMA_TYPE', where + ' must be an array'); return []; };
  function bad0(id, detail){ V0.push({id, detail}); }
  const V0 = [];
  const V=[]; const bad=(id,detail)=>V.push({id,detail});
  const allow = buildAllowlist(inputs, reg);
  const inputNumbers = new Set();
  ['ideal_size','price_range'].forEach(k=>numbersIn(inputs[k]).forEach(n=>inputNumbers.add(n)));
  (inputs.locations||[]).forEach(l=>numbersIn(l).forEach(n=>inputNumbers.add(n)));
  const checkTokens=(text, where)=>{
    tokens(text).forEach(t=>{ if(!allow.has(t)) bad('TOKEN_NOT_ALLOWLISTED', where+': "'+t+'"'); });
    numbersIn(text).forEach(n=>{ if(!inputNumbers.has(n) && !reg.size_bands.join(' ').includes(n)) bad('NUMBER_NOT_ALLOWLISTED', where+': '+n); });
  };
  // 1 schema
  const topKeys = Object.keys(draft||{});
  ['business_context','profile','rubric'].forEach(k=>{ if(!topKeys.includes(k)) bad('SCHEMA_MISSING_KEY', k); });
  topKeys.forEach(k=>{ if(!['business_context','profile','rubric'].includes(k)) bad('SCHEMA_EXTRA_KEY', k); });
  if(V.length){ V0.forEach(x=>V.push(x)); return {violations:V, cost_usd:0}; }
  const prof = draft.profile||{};
  const profKeys = reg.profile_keys;
  Object.keys(prof).forEach(k=>{ if(!profKeys.includes(k)) bad('SCHEMA_EXTRA_KEY','profile.'+k); });
  // injection screen on downstream-prompt fields
  const injFields = JSON.stringify([prof.outreach_angles||[], draft.business_context&&draft.business_context.notes||'']);
  if(/https?:\/\//i.test(injFields)) bad('INJECTION_URL','url in downstream field');
  if(/ignore (your|the) (brief|instructions|rules)|disregard|override/i.test(injFields)) bad('INJECTION_OVERRIDE','override phrase in downstream field');
  // 2 sources + queries
  let cost = 0; const seenQ = new Set();
  const locTokens = new Set(); (inputs.locations||[]).forEach(l=>tokens(l).forEach(t=>locTokens.add(t)));
  const catTokens = new Set(); reg.gazetteer.categories.forEach(c=>tokens(c).forEach(t=>catTokens.add(t)));
  for(const src of arr(prof.sources,'profile.sources')){
    Object.keys(src).forEach(k=>{ if(!['source','queries','locations','platforms','enabled'].includes(k)) bad('SCHEMA_EXTRA_KEY', 'source.'+k); });
    if(!src.source) bad('SCHEMA_MISSING_KEY', 'source.source');
    if(src.source==='tavily_social' && typeof src.enabled !== 'boolean') bad('SCHEMA_MISSING_KEY', 'source.enabled (tavily_social needs an explicit boolean)');
    const spec = reg.sources[src.source];
    if(!spec){ bad('SOURCE_UNKNOWN', String(src.source)); continue; }
    const qs = arr(src.queries,'queries');
    if(qs.length > spec.max_queries) bad('QUERY_CAP', src.source+': '+qs.length+' > '+spec.max_queries);
    cost += src.source==='apify_maps' ? qs.length * spec.unit_price_usd * spec.max_results_per_query : qs.length * spec.unit_price_usd;
    for(const q of qs){
      if(!q || !String(q).trim()){ bad('QUERY_EMPTY', src.source); continue; }
      const key = canon(q).replace(/\s+/g,' ');
      if(seenQ.has(key)) bad('QUERY_DUP', q); seenQ.add(key);
      const qt = tokens(q);
      const hasLoc = qt.some(t=>locTokens.has(t)); const hasCat = qt.some(t=>catTokens.has(t));
      if(src.source==='apify_maps' && !(hasLoc && hasCat)) bad('QUERY_GRAMMAR_MAPS', q);
      if(src.source==='tavily_research' && !hasLoc) bad('QUERY_NO_LOCATION', q);
      if(src.source==='tavily_social' && !(src.locations||[]).some(l=>locTokens.has(canon(l)))) bad('QUERY_NO_LOCATION', src.source+' source locations');
      checkTokens(q, 'query');
      for(const ex of (inputs.exclusions||[])){
        const exT = tokens(ex); if(exT.length && exT.every(t=>qt.includes(t))) bad('EXCLUSION_CONTRADICTED', q+' vs exclusion "'+ex+'"');
      }
    }
    if(src.source==='tavily_social'){ (src.platforms||[]).forEach(p=>{ if(!spec.platforms.includes(p)) bad('SOURCE_UNKNOWN','platform '+p); }); }
  }
  // 3 preservation
  const profLocText = canon(JSON.stringify(prof.sources||[])) + ' ' + canon(JSON.stringify((draft.business_context||{}).locations||[]));
  (inputs.locations||[]).forEach(l=>{ if(!tokens(l).every(t=>profLocText.includes(t))) bad('PRESERVE_LOCATION', l); });
  const profExcl = (prof.exclusions||[]).map(canon);
  (inputs.exclusions||[]).forEach(e=>{ if(!profExcl.some(x=>x.includes(canon(e)) || canon(e).includes(x))) bad('PRESERVE_EXCLUSION', e); });
  // 4 fields + size
  arr(prof.research_fields,'research_fields').forEach(f=>{ if(!reg.research_fields.includes(f)) bad('FIELD_UNKNOWN', f); });
  const bands = (prof.size_fit && prof.size_fit.ideal_bands) || [];
  bands.forEach(b=>{ if(!reg.size_bands.includes(b)) bad('SIZE_BAND_INVALID', b); });
  arr(prof.decision_maker_titles,'dm_titles').forEach(t=>checkTokens(t,'dm_title'));
  arr(prof.outreach_angles,'outreach_angles').forEach(a=>checkTokens(a,'outreach_angle'));
  // 5 rubric — OBJECT contract (SF7 reads rubric.fit_criteria; SF1-SPEC shape)
  const rub = draft.rubric;
  if(!rub || typeof rub !== 'object' || Array.isArray(rub)) bad('SCHEMA_TYPE', 'rubric must be an object {fit_criteria, timing_triggers, llm_judgement_max, bands}');
  const rubObj = (rub && typeof rub === 'object' && !Array.isArray(rub)) ? rub : {};
  Object.keys(rubObj).forEach(k=>{ if(!['fit_criteria','timing_triggers','llm_judgement_max','bands','coverage'].includes(k)) bad('SCHEMA_EXTRA_KEY', 'rubric.'+k); });
  if(rubObj.llm_judgement_max === undefined) bad('SCHEMA_MISSING_KEY', 'rubric.llm_judgement_max');
  else if(rubObj.llm_judgement_max !== reg.rubric.max_judge_points) bad('RUBRIC_JUDGE', 'llm_judgement_max must be '+reg.rubric.max_judge_points);
  if(rubObj.bands !== undefined){ const b = rubObj.bands; if(!b || typeof b !== 'object' || !(Number(b.A) > Number(b.B) && Number(b.B) > Number(b.C) && Number(b.A) <= 100)) bad('RUBRIC_BANDS', 'bands must be {A>B>C, A<=100}'); }
  if(!Array.isArray(rubObj.fit_criteria)) bad('SCHEMA_TYPE', 'rubric.fit_criteria must be an array');
  arr(rubObj.timing_triggers,'timing_triggers').forEach(t=>{ if(!t.name || !t.signal) bad('SCHEMA_TYPE','timing_trigger needs name+signal'); if((t.max_points||0) > 30) bad('RUBRIC_TIMING', t.name+' over 30'); if(t.decay_days !== undefined && (t.decay_days < 7 || t.decay_days > 90)) bad('RUBRIC_TIMING', t.name+' decay_days out of 7..90'); checkTokens(String(t.name||''),'timing_name'); });
  let total=0, judge=0; const names=new Set();
  for(const c of arr(rubObj.fit_criteria,'fit_criteria')){
    total += c.max_points||0;
    if(!c.name) { bad('SCHEMA_TYPE', 'rubric criterion missing name'); } else { if(names.has(c.name)) bad('RUBRIC_NAME_DUP', c.name); names.add(c.name); }
    if((c.max_points||0) > reg.rubric.max_criterion_points) bad('RUBRIC_SUM', 'criterion over cap: '+c.name);
    if(c.kind==='deterministic'){
      const chk = reg.machine_checks[c.machine_check];
      if(!chk) bad('RUBRIC_CHECK_UNKNOWN', c.name+': '+c.machine_check);
      else (chk.params.required||[]).forEach(p=>{ if(!c.params || !(p in c.params)) bad('RUBRIC_CHECK_PARAMS', c.name+' missing '+p); });
      // SF7 family contract: a deterministic criterion only executes if its NAME
      // (and verify text, for category) matches SF7's classifyCriterion patterns.
      const nm = String(c.name||'').toLowerCase(); const hv = String(c.how_to_verify||'');
      if(c.machine_check==='location_match' && !/location|city|geograph|footprint|area|region/.test(nm)) bad('RUBRIC_FAMILY_MISMATCH', c.name+' -> SF7 location family needs location/city/area in the name');
      if(c.machine_check==='facebook_linkage' && !/facebook/.test(nm)) bad('RUBRIC_FAMILY_MISMATCH', c.name+' -> SF7 facebook family needs facebook in the name');
      if(c.machine_check==='size_fit' && !/size|headcount/.test(nm)) bad('RUBRIC_FAMILY_MISMATCH', c.name+' -> SF7 size branch needs size/headcount in the name');
      if(c.machine_check==='review_volume' && !(/review/.test(nm) && /count|volume|number/.test(nm+' '+hv.toLowerCase()))) bad('RUBRIC_FAMILY_MISMATCH', c.name+' -> SF7 review_volume needs review + count/volume/number');
      if(c.machine_check==='business_type_match'){
        if(!/category|business type|property type|firm type/.test(nm)) bad('RUBRIC_FAMILY_MISMATCH', c.name+' -> SF7 category family needs category/business type in the name');
        const m = hv.match(/matches any of:\s*(.+)/i);
        if(!m) bad('RUBRIC_VERIFY_MISSING', c.name+' -> how_to_verify must contain "matches any of: <terms>" for SF7 categoryTerms');
        else { const inc = m[1].split(/\s+but\s+|\s+however\s+/).flatMap(x=>x.split(/[,;]/)).map(x=>x.trim()).filter(Boolean).filter(x=>!/\b(not|no|never|without)\b/i.test(x)); if(!inc.length) bad('RUBRIC_VERIFY_MISSING', c.name+' -> no include terms in matches-any-of list'); }
      }
    } else if(c.kind==='research_only'){ judge += c.max_points||0; }
    else bad('SCHEMA_TYPE','rubric kind '+c.kind);
  }
  if(total !== reg.rubric.max_total_points) bad('RUBRIC_SUM', 'fit_criteria sum '+total+' must be exactly '+reg.rubric.max_total_points);
  if(judge > reg.rubric.max_judge_points) bad('RUBRIC_JUDGE', 'judge '+judge+' > '+reg.rubric.max_judge_points);
  // 6 cost
  if(cost > reg.cost.worst_case_run_ceiling_usd) bad('COST_CEILING', 'recomputed $'+cost.toFixed(3)+' > $'+reg.cost.worst_case_run_ceiling_usd);
  V0.forEach(x=>V.push(x));
  return {violations:V, cost_usd: Math.round(cost*1000)/1000};
}


function djb2(s){let h=5381;const str=String(s);for(let i=0;i<str.length;i++){h=((h<<5)+h+str.charCodeAt(i))|0;}return ('0000000'+(h>>>0).toString(16)).slice(-8);}
function renderSummary(draft, cost){
  const L=[]; const bc=draft.business_context||{}; const p=draft.profile||{};
  L.push('PLAN SUMMARY (code-rendered)');
  L.push('Business: '+(bc.business_name||''));
  L.push('Locations: '+((bc.locations||[]).join(', ')));
  L.push('Exclusions: '+((p.exclusions||[]).join(', ')||'none'));
  for(const s of (p.sources||[])){ L.push('Source '+s.source+':'); for(const q of (s.queries||[])) L.push('  - '+q); }
  L.push('Research fields: '+((p.research_fields||[]).join(', ')));
  L.push('Size fit: '+(((p.size_fit||{}).ideal_bands||[]).join(', ')));
  L.push('Decision-maker titles: '+((p.decision_maker_titles||[]).join(', ')));
  L.push('Rubric:');
  for(const c of ((draft.rubric||{}).fit_criteria||[])) L.push('  - '+c.name+': '+c.max_points+' pts ('+c.kind+(c.machine_check?'/'+c.machine_check:'')+')');
  L.push('Timing triggers: '+(((draft.rubric||{}).timing_triggers||[]).map(t=>t.name).join(', ')||'none'));
  L.push('Bands: '+JSON.stringify((draft.rubric||{}).bands||{})+' | judge max: '+((draft.rubric||{}).llm_judgement_max));
  L.push('Recomputed worst-case cost: $'+Number(cost).toFixed(3));
  L.push('Registry: v'+REG.version);
  return L.join('\n');
}

const route = $('Route').first().json;
const row = $('Load Profile').first().json || {};
const reasons = [];
if (!row.id) reasons.push('PROFILE_NOT_FOUND');
else if (row.status !== 'draft') reasons.push('NOT_DRAFT');
const meta = (row.business_context || {})._sf0 || null;
if (row.id && !meta) reasons.push('NO_SF0_META');
let summaryNow = '';
if (meta) {
  if (meta.registry_version !== REG.version) reasons.push('REGISTRY_CHANGED');
  const draft = {business_context: Object.assign({}, row.business_context, {}), profile: row.profile, rubric: row.rubric};
  delete draft.business_context._sf0;
  const r = validateDraft(draft, meta.inputs_snapshot, REG);
  if (r.violations.length) reasons.push('REVALIDATION_FAILED:' + r.violations.map(v=>v.id).join(','));
  summaryNow = renderSummary(draft, meta.cost_usd);
  if (djb2(summaryNow) !== meta.summary_hash) reasons.push('SUMMARY_HASH_CHANGED');
